package com.example.inventoryservicefeb25.model; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.time.Instant;
@Entity @Table(name="inventory_reservations",uniqueConstraints={@UniqueConstraint(name="uk_reservation_id",columnNames="reservation_id"),@UniqueConstraint(name="uk_reservation_order_product",columnNames={"order_id","product_id"})}) @Getter @Setter public class InventoryReservation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="reservation_id",nullable=false,length=80) private String reservationId; @Column(name="order_id",nullable=false) private Long orderId; @Column(name="product_id",nullable=false) private Long productId; @Column(nullable=false) private int quantity; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ReservationStatus status; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant expiresAt; }
